export const COMMUNITY_KINDS=['code','patch','creator'];
export const isCommunityPreview=(url=location.href)=>{const u=new URL(url);return ['localhost','127.0.0.1','[::1]'].includes(u.hostname)&&u.searchParams.get('preview')==='1'};
export function safeCommunityUrl(value,{image=false}={}){if(!value)return '';if(image&&/^assets\/creators\/[A-Za-z0-9_.-]+$/.test(value))return value;let u;try{u=new URL(value)}catch{throw Error('Enter a complete https:// link.')}if(u.protocol!=='https:'||u.username||u.password)throw Error('Only secure https:// links are allowed.');if(image&&!['yt3.googleusercontent.com','yt3.ggpht.com','i.ytimg.com'].includes(u.hostname))throw Error('Use a YouTube image link or a local creator image.');return u.href;}
const fields={code:['code','rewards','status','expires_on','checked_on','source_url','note','status_override','dislike_threshold'],patch:['title','version','released_on','source_url','summary','source_verified'],creator:['name','description','channel_url','avatar_url','creator_code','featured','videos']};
export function blankCommunityEntry(kind){if(kind==='code')return {code:'',rewards:'',status:'Active',status_override:'Auto',dislike_threshold:'10',expires_on:'',checked_on:'',source_url:'',note:''};if(kind==='patch')return {title:'',version:'',released_on:'',source_url:'',summary:'',source_verified:false};if(kind==='creator')return {name:'',description:'',channel_url:'',avatar_url:'',creator_code:'',featured:false,videos:[]};throw Error('Unknown entry type.');}
function date(value,label){if(value&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||new Date(value+'T00:00:00Z').toISOString().slice(0,10)!==value))throw Error(label+' must be a real date.');}
export function validateCommunityEntry(kind,value,{publish=false}={}){if(!fields[kind]||!value||Array.isArray(value)||typeof value!=='object')throw Error('Invalid community entry.');if(Object.keys(value).some(k=>!fields[kind].includes(k)))throw Error('Unknown entry field.');const v={...blankCommunityEntry(kind),...structuredClone(value)};for(const [k,x] of Object.entries(v)){if(['featured','source_verified'].includes(k)){if(typeof x!=='boolean')throw Error('Invalid checkbox value.');}else if(k!=='videos'){if(typeof x!=='string'||x.length>(['summary','description','note'].includes(k)?5000:1000))throw Error('Invalid or overly long '+k+'.');v[k]=x.trim();}}for(const k of ['expires_on','checked_on','released_on'])if(k in v)date(v[k],k);if(v.source_url)v.source_url=safeCommunityUrl(v.source_url);if(kind==='code'){if(!['Auto','Working','Not working'].includes(v.status_override))throw Error('Choose Auto, Working or Not working.');if(!/^\d{1,6}$/.test(v.dislike_threshold)||Number(v.dislike_threshold)>100000)throw Error('Dislike threshold must be an integer from 0 to 100000.');if(!['Active','Unverified','Expired'].includes(v.status))throw Error('Choose Active, Unverified or Expired.');if(v.code&&!/^[A-Za-z0-9_-]{1,80}$/.test(v.code))throw Error('Codes can contain letters, numbers, underscores and hyphens.');if(publish&&(!v.code||!v.rewards))throw Error('Add the code and reward description before publishing.');}
if(kind==='patch'&&publish&&(!v.title||!v.released_on||!v.source_url||!v.source_verified))throw Error('Add a title, release date and source, then confirm it is an official developer announcement.');
if(kind==='creator'){if(v.channel_url){v.channel_url=safeCommunityUrl(v.channel_url);if(!['youtube.com','www.youtube.com'].includes(new URL(v.channel_url).hostname))throw Error('Use the creator’s YouTube channel link.');}if(v.avatar_url)v.avatar_url=safeCommunityUrl(v.avatar_url,{image:true});if(!Array.isArray(v.videos)||v.videos.length>12)throw Error('Use up to 12 selected videos.');v.videos=v.videos.map(video=>{if(!video||Object.keys(video).some(k=>!['title','url','topic','thumbnail'].includes(k)))throw Error('Invalid video.');if(typeof video.title!=='string'||!video.title.trim()||video.title.length>250)throw Error('Add a video title.');const url=safeCommunityUrl(video.url),u=new URL(url);if(!['youtube.com','www.youtube.com','youtu.be'].includes(u.hostname))throw Error('Use a YouTube video link.');return {title:video.title.trim(),url,topic:String(video.topic||'').slice(0,80),thumbnail:video.thumbnail?safeCommunityUrl(video.thumbnail,{image:true}):''};});if(publish&&(!v.name||!v.description||!v.channel_url||!v.avatar_url))throw Error('Add the creator name, description, channel link and profile image.');}return v;}
export function effectiveCodeStatus(entry,today=new Date().toISOString().slice(0,10)){return entry.status==='Expired'||entry.expires_on&&entry.expires_on<today?'Expired':entry.status;}
export function publicCommunityEntries(rows,{draftId=''}={}){return rows.filter(r=>r.published||(draftId&&r.id===draftId)).map(r=>({id:r.id,kind:r.kind,published_at:r.published_at,content:structuredClone(r.id===draftId?r.draft:r.published)}));}
export const communityLabel=(kind,v)=>kind==='code'?v?.code||'Untitled code':kind==='patch'?v?.title||'Untitled patch notes':v?.name||'Untitled creator';

export function codeWorkingStatus(entry,votes={}){if(entry.status_override==='Working'||entry.status_override==='Not working')return entry.status_override;return effectiveCodeStatus(entry)==='Expired'||Number(votes.dislikes||0)>Number(entry.dislike_threshold??10)?'Not working':'Working';}
export function patchStatus(entry,today=new Date().toISOString().slice(0,10)){return entry.released_on>today?'Upcoming patch':'Patch notes';}
